using System.ComponentModel.DataAnnotations;

namespace FleetManagerApi.DTOs
{
    // Deliberately narrow: only the fields that make sense to set at creation time.
    // VehicleID is excluded — it will be generated by the database.
    // Status is excluded — it will be set to "Available" by default.
    // Model, LicensePlate, and DailyRentalPrice are required.
    // This DTO is used for creating a new vehicle.
    public class CreateVehicleDtos
    {
        [Key]
        public int VehicleID { get; set; }

        [Required]
        [StringLength(20)]
        public string LicensePlate { get; set; } = string.Empty;

        [Required]
        [StringLength(50)]
        public string Model { get; set; } = string.Empty;

        [Required]
        public decimal DailyRentalPrice { get; set; }

    }

    // Deliberately narrow: only the fields that make sense to edit after creation.
    // VehicleID is excluded — it should never be changed.
    // Model, LicensePlate, DailyRentalPrice, and Status are required.
    // Status can be "Available", "Rented", or "Maintenance".
    // This DTO is used for updating an existing vehicle.

    public class UpdateVehicleDtos {

        [Required]
        [StringLength(20)]
        public string LicensePlate { get; set; } = string.Empty;

        [Required]
        [StringLength(50)]
        public string Model { get; set; } = string.Empty;

        [Required]
        public decimal DailyRentalPrice { get; set; }

        [Required]
        [StringLength(50)]
        public string Status { get; set; } = string.Empty;


    }
}
